async function loadRoom(){const params=new URLSearchParams(location.search),id=params.get('id');if(!uuidRE.test(id||''))throw new Error('This room link is invalid. Return to Rooms and choose a room.');setStatus('Finding this room…');const r=await withTimeout(()=>db.from('spike_rooms').select('*').eq('id',id).maybeSingle(),15000,'Finding this room');if(r.error)throw r.error;if(!r.data)throw new Error('This room is unavailable or private. Ask the host for an invitation.');room=r.data;if(room.status==='ended')throw new Error('This room has ended. Browse Rooms to find another conversation.');setStatus('Confirming your membership…');let join=await withTimeout(()=>db.rpc('spike_rooms_join',{p_room_id:id}),20000,'Confirming room membership');if(join.error&&!(join.error.message||'').toLowerCase().includes('already'))throw join.error;
const topName=$('roomTopName'),titleNode=$('roomTitle'),descriptionNode=$('roomDescription'),privacyNode=$('roomPrivacyLabel'),livePill=$('roomLivePill');if(topName)topName.textContent=room.title||'Live room';if(titleNode)titleNode.textContent=room.title;if(descriptionNode)descriptionNode.textContent=room.description||'';if(privacyNode)privacyNode.textContent=room.visibility==='private'?'Private room':'Public room';if(livePill){livePill.innerHTML=room.status==='scheduled'?'<i class="fa-regular fa-clock"></i> UPCOMING':'<i class="live-dot"></i> LIVE';if(room.status==='scheduled')livePill.style.color='#fcd34d'}
// Chat is the primary room experience: establish it before optional side panels. Update UI as soon as messages arrive.
setStatus('Loading conversation…');
const messagesPromise=withTimeout(()=>loadRoomMessages(),18000,'Loading room messages');
const membersPromise=withTimeout(()=>refreshRoomMembers(),15000,'Loading room members').catch(e=>{console.warn('[SPIKE Rooms] Member panel is temporarily unavailable:',e.message);roomMembers=[];roomFormerMembers=[];roomPendingInvites=[];roomGiftEligibility=new Map();renderStage();const people=$('peopleDirectory');if(people)people.innerHTML='<div class="speaker-placeholder">Member details are temporarily unavailable. Chat is still connected.</div>'});
await messagesPromise;
setStatus('Connecting live updates…');
void withTimeout(()=>loadGiftCatalog(),15000,'Loading room gifts').catch(e=>console.info('[SPIKE Rooms] Gift panel deferred:',e.message));
void withTimeout(()=>loadFriendsForInvites(),20000,'Loading invite contacts').catch(e=>console.info('[SPIKE Rooms] Invite contacts deferred:',e.message));
await membersPromise;
await connectRoomChannel(id);roomHistoryUrl=location.href;history.pushState({spikeRoomGuard:true},'',roomHistoryUrl);window.addEventListener('popstate',()=>{if(!roomMode||!room)return;history.pushState({spikeRoomGuard:true},'',roomHistoryUrl);if(!leavePending)void leaveRoom()});}
async function refreshRoomState(){if(!room?.id)return;const r=await db.from('spike_rooms').select('active_host_id,status,allow_chat,allow_speaker_requests,visibility,max_participants,title,description').eq('id',room.id).maybeSingle();if(r.error)throw r.error;if(r.data){Object.assign(room,r.data);renderGiftRecipients();const topName=$('roomTopName'),titleNode=$('roomTitle'),descriptionNode=$('roomDescription'),livePill=$('roomLivePill'),chatInput=$('roomChatInput'),chatSend=$('roomChatForm')?.querySelector('button[type="submit"]');if(topName)topName.textContent=room.title;if(titleNode)titleNode.textContent=room.title;if(descriptionNode)descriptionNode.textContent=room.description||'';if(livePill)livePill.innerHTML=room.status==='scheduled'?'<i class="fa-regular fa-clock"></i> UPCOMING':'<i class="live-dot"></i> LIVE';const chatDisabled=!room.allow_chat||room.status!=='live';if(chatInput){chatInput.disabled=chatDisabled;chatInput.placeholder=!room.allow_chat?'Room chat is disabled by the host':room.status!=='live'?'Chat opens when the room starts':'Write a message…'}if(chatSend)chatSend.disabled=chatDisabled}}
async function refreshRoomMembers(){
 const [r,invites]=await Promise.all([
  withTimeout(()=>db.from('spike_room_members').select('room_id,user_id,role,member_state,is_muted,speaker_requested,joined_at,left_at').eq('room_id',room.id).order('joined_at',{ascending:true}).limit(200),12000,'Loading room members'),
  withTimeout(()=>db.from('spike_room_invites').select('id,invitee_id,inviter_id,status,created_at,responded_at').eq('room_id',room.id).in('status',['pending','accepted']).order('created_at',{ascending:true}).limit(200),12000,'Loading room invitations')
 ]);
 if(r.error)throw r.error;
 const allMembershipRows=r.data||[];roomMembers=allMembershipRows.filter(m=>m.member_state==='active');roomFormerMembers=allMembershipRows.filter(m=>m.member_state==='left');
 const activeIds=new Set(roomMembers.map(m=>String(m.user_id)));
 roomPendingInvites=(invites.error?[]:(invites.data||[])).filter(i=>i.status==='pending'&&!activeIds.has(String(i.invitee_id))&&String(i.invitee_id)!==String(me.id));
 try{const eligibility=await withTimeout(()=>db.rpc('spike_room_gift_recipient_eligibility',{p_room_id:room.id}),8000,'Checking gift eligibility');if(!eligibility.error)roomGiftEligibility=new Map((eligibility.data||[]).map(x=>[String(x.user_id),x.is_verified===true]));else{roomGiftEligibility=new Map();console.info('[SPIKE Rooms] Gift eligibility unavailable:',eligibility.error.message)}}catch(e){roomGiftEligibility=new Map();console.info('[SPIKE Rooms] Gift eligibility deferred:',e.message)}
 const myActiveRole=roomMembers.find(m=>m.user_id===me.id)?.role;if(voiceSpeakerPc&&myActiveRole!=='speaker')void closeStageSpeaker();
 roomProfiles=await getProfiles([room.host_id,...roomMembers.map(m=>m.user_id),...roomFormerMembers.map(m=>m.user_id),...roomPendingInvites.map(i=>i.invitee_id)]);
 renderGiftRecipients();syncHostSpeakerMembers();renderStage();void syncVoicePeerChannels();
}
async function fetchRoomMessages(before=null){
 let q=db.from('spike_room_messages').select('id,room_id,sender_id,body,created_at,deleted_at,edited_at,reply_to_message_id,pinned_at,pinned_by,paid_reward_kind,paid_reward_coin_cost').eq('room_id',room.id).is('deleted_at',null).order('created_at',{ascending:false}).limit(60);
 if(before)q=q.or(`created_at.lt.${before.created_at},and(created_at.eq.${before.created_at},id.lt.${before.id})`);
 let r=await q;
 if(r.error&&/reply_to_message_id|pinned_at|edited_at|column/i.test(r.error.message||'')){
  let fallback=db.from('spike_room_messages').select('id,room_id,sender_id,body,created_at,deleted_at').eq('room_id',room.id).is('deleted_at',null).order('created_at',{ascending:false}).limit(60);
  if(before)fallback=fallback.or(`created_at.lt.${before.created_at},and(created_at.eq.${before.created_at},id.lt.${before.id})`);r=await fallback;
 }
 if(r.error)throw r.error;return r.data||[]
}
async function loadOlderRoomMessages(){if(roomOlderLoading||!roomHasOlderMessages||!roomMessages.length)return;roomOlderLoading=true;const host=$('roomChatMessages'),oldHeight=host?.scrollHeight||0,oldTop=host?.scrollTop||0;const first=roomMessages[0];try{const rows=await fetchRoomMessages(first);roomHasOlderMessages=rows.length===60;if(rows.length){const known=new Set(roomMessages.map(m=>m.id));const fresh=rows.reverse().filter(m=>!known.has(m.id));roomMessages=[...fresh,...roomMessages];const extra=await getProfiles(fresh.map(m=>m.sender_id));extra.forEach((v,k)=>roomProfiles.set(k,v));await loadRoomReactions();await loadRoomPaidRewards();renderRoomMessages(false);if(host)host.scrollTop=host.scrollHeight-oldHeight+oldTop}}catch(e){notice(e.message||'Older messages could not be loaded.','error')}finally{roomOlderLoading=false;renderRoomMessages(false)}}
async function loadPinnedRoomMessages(){if(!$('roomPinnedOnly')?.checked)return;try{const r=await db.from('spike_room_messages').select('id,room_id,sender_id,body,created_at,deleted_at,edited_at,reply_to_message_id,pinned_at,pinned_by,paid_reward_kind,paid_reward_coin_cost').eq('room_id',room.id).not('pinned_at','is',null).is('deleted_at',null).order('pinned_at',{ascending:false}).limit(60);if(r.error)throw r.error;roomPinnedMessages=r.data||[];await loadRoomReactions();await loadRoomPaidRewards();const missing=roomPinnedMessages.filter(m=>!roomProfiles.has(String(m.sender_id))).map(m=>m.sender_id);const profiles=await getProfiles(missing);profiles.forEach((v,k)=>roomProfiles.set(k,v));renderRoomMessages(false)}catch(e){notice(e.message||'Pinned messages are unavailable. Apply the latest Rooms migration.','error')}}
async function loadRoomMessages(){const rows=await fetchRoomMessages();roomHasOlderMessages=rows.length===60;roomMessages=rows.reverse();await loadRoomReactions();await loadRoomPaidRewards();const missing=roomMessages.map(m=>m.sender_id).filter(id=>!roomProfiles.has(String(id)));const extra=await getProfiles(missing);extra.forEach((p,id)=>roomProfiles.set(id,p));renderRoomMessages()}
async function loadRoomReactions(){if(!room?.id){roomReactions=[];return}const ids=[...new Set(($('roomPinnedOnly')?.checked?roomPinnedMessages:roomMessages).map(m=>m.id).filter(Boolean))];if(!ids.length){roomReactions=[];return}try{const chunks=[];for(let i=0;i<ids.length;i+=60){const r=await db.rpc('spike_room_get_reactions',{p_message_ids:ids.slice(i,i+60)});if(r.error)throw r.error;chunks.push(...(r.data||[]))}roomReactions=chunks}catch(e){roomReactions=[];console.info('[SPIKE Rooms] Message reactions are unavailable until the latest room migration is applied:',e.message)}}
async function loadRoomPaidRewards(){if(!room?.id){roomPaidRewards=[];return}const ids=[...new Set(($('roomPinnedOnly')?.checked?roomPinnedMessages:roomMessages).map(m=>m.id).filter(Boolean))];if(!ids.length){roomPaidRewards=[];return}try{const r=await db.rpc('spike_room_get_paid_message_rewards',{p_room_id:room.id,p_message_ids:ids});if(r.error)throw r.error;roomPaidRewards=r.data||[]}catch(e){roomPaidRewards=[];console.info('[SPIKE Rooms] Paid message rewards are unavailable until the latest room migration is applied:',e.message)}}
function renderRoomMessages(shouldScroll=true){
 const host=$('roomChatMessages');if(!host)return;const nearBottom=host.scrollHeight-host.scrollTop-host.clientHeight<90;
 const source=$('roomPinnedOnly')?.checked?roomPinnedMessages:roomMessages;const filtered=source.filter(m=>!roomChatSearch||String(m.body||'').toLowerCase().includes(roomChatSearch));
 const olderButton=roomHasOlderMessages&&!$('roomPinnedOnly')?.checked?'<button type="button" class="room-load-older" id="loadOlderRoomMessages">Load older messages</button>':'';
 host.innerHTML=olderButton+(filtered.length?filtered.map(m=>{const p=roomProfiles.get(String(m.sender_id))||{};const mine=m.sender_id===me.id;const canDelete=mine||isModerator();const canPin=isModerator();const reactions=['👍','❤️','😂','🔥','👏'];const mineReactions=roomReactions.filter(x=>x.message_id===m.id);const reactionMarkup=reactions.map(emoji=>{const users=mineReactions.filter(x=>x.reaction===emoji);return `<button type="button" class="room-reaction${users.some(x=>x.user_id===me.id)?' is-active':''}" data-message-reaction="${esc(emoji)}" data-message-id="${esc(m.id)}" aria-pressed="${users.some(x=>x.user_id===me.id)}" aria-label="React ${esc(emoji)}${users.length?' '+users.length:''}">${emoji}<span>${users.length||''}</span></button>`}).join('');const paidOptions=[{code:'spark_2',emoji:'🌟',cost:2,label:'Spark'},{code:'purple_3',emoji:'💜',cost:3,label:'Purple heart'},{code:'bolt_5',emoji:'⚡',cost:5,label:'Bolt'},{code:'crown_7',emoji:'👑',cost:7,label:'Crown'},{code:'diamond_10',emoji:'💎',cost:10,label:'Diamond'}];const paidMarkup=!mine?paidOptions.map(o=>{const row=roomPaidRewards.find(x=>x.message_id===m.id&&x.reward_code===o.code);return `<button type="button" class="room-paid-reaction" data-message-paid-reaction="${o.code}" data-message-id="${esc(m.id)}" data-reward-cost="${o.cost}" aria-label="${o.label}, ${o.cost} SP COINS">${o.emoji}<small>${o.cost} SP</small>${row?.reward_count?`<span>${Number(row.reward_count)}</span>`:''}</button>`}).join(''):'';const parent=m.reply_to_message_id?([...roomMessages,...roomPinnedMessages].find(x=>x.id===m.reply_to_message_id)):null;const parentProfile=parent?roomProfiles.get(String(parent.sender_id))||{}:{};return `<article class="room-chat-message ${m.pinned_at?'is-pinned':''}" data-message-id="${esc(m.id)}" tabindex="0" aria-label="Message from ${esc(profileName(p))}. Long press or open message actions"><div class="chat-message-avatar">${avatar(p)}</div><div class="chat-message-copy"><div class="chat-message-meta"><strong>${esc(profileName(p))}${mine?' · You':''}</strong><time>${esc(formatTime(m.created_at))}${m.edited_at?' · edited':''}</time>${m.pinned_at?'<span class="room-pinned-label">PINNED</span>':''}</div>${parent?`<button type="button" class="room-reply-context" data-jump-message="${esc(parent.id)}">Replying to ${esc(profileName(parentProfile))}: ${esc(parent.body.slice(0,100))}</button>`:''}<div class="chat-message-body">${esc(m.body)}</div>${m.paid_reward_kind==='paid_comment'?'<span class="room-paid-comment-tag">PAID COMMENT</span>':''}<div class="room-message-tools" hidden><div class="room-message-reactions" aria-label="Free message reactions">${reactionMarkup}</div><div class="room-message-paid-reactions" aria-label="Paid reactions">${paidMarkup}</div><div class="room-message-actions"><button type="button" data-message-reply="${esc(m.id)}">Reply</button>${!mine?`<button type="button" data-message-paid-comment="${esc(m.id)}">Paid comment · 2–5 SP</button>`:''}<button type="button" data-message-copy="${esc(m.id)}">Copy</button>${canPin?`<button type="button" data-message-pin="${esc(m.id)}" data-pin-state="${m.pinned_at?'1':'0'}">${m.pinned_at?'Unpin':'Pin'}</button>`:''}<button type="button" data-message-report="${esc(m.id)}">Report</button>${mine?`<button type="button" data-message-edit="${esc(m.id)}">Edit</button>`:''}${canDelete?`<button type="button" data-message-delete="${esc(m.id)}">Delete</button>`:''}</div></div></div></article>`}).join(''):'<div class="chat-empty">'+(roomChatSearch?'No messages match your search.':$('roomPinnedOnly')?.checked?'There are no pinned messages in the loaded conversation.':'Messages from people in this room will appear here.')+'</div>');
 if(shouldScroll||nearBottom)host.scrollTop=host.scrollHeight;
}
let roomMessagePressTimer=null,roomMessagePressTarget=null,roomMessagePressStartX=0,roomMessagePressStartY=0,roomMessagePressFired=false,roomMessageSuppressClick=false;
function closeRoomMessageActions(except=null){document.querySelectorAll('.room-chat-message.is-actions-open').forEach(node=>{if(node===except)return;node.classList.remove('is-actions-open');const tools=node.querySelector('.room-message-tools');if(tools)tools.hidden=true;node.setAttribute('aria-expanded','false')})}
function openRoomMessageActions(node){if(!node)return;closeRoomMessageActions(node);node.classList.add('is-actions-open');const tools=node.querySelector('.room-message-tools');if(tools)tools.hidden=false;node.setAttribute('aria-expanded','true');roomMessagePressFired=true;roomMessageSuppressClick=true;setTimeout(()=>{roomMessageSuppressClick=false},700);}
function cancelRoomMessagePress(){if(roomMessagePressTimer){clearTimeout(roomMessagePressTimer);roomMessagePressTimer=null}roomMessagePressTarget=null}
function bindRoomMessageLongPress(){const host=$('roomChatMessages');if(!host||host.dataset.longPressBound==='1')return;host.dataset.longPressBound='1';host.addEventListener('pointerdown',e=>{const node=e.target.closest('.room-chat-message');if(!node||e.target.closest('button'))return;if(e.pointerType==='mouse'&&e.button!==0)return;cancelRoomMessagePress();roomMessagePressTarget=node;roomMessagePressStartX=e.clientX;roomMessagePressStartY=e.clientY;roomMessagePressFired=false;roomMessagePressTimer=setTimeout(()=>{roomMessagePressTimer=null;if(roomMessagePressTarget===node){openRoomMessageActions(node);if(navigator.vibrate)try{navigator.vibrate(12)}catch(_){}}},480)});host.addEventListener('pointermove',e=>{if(!roomMessagePressTimer)return;if(Math.hypot(e.clientX-roomMessagePressStartX,e.clientY-roomMessagePressStartY)>12)cancelRoomMessagePress()});host.addEventListener('pointerup',cancelRoomMessagePress);host.addEventListener('pointercancel',cancelRoomMessagePress);host.addEventListener('contextmenu',e=>{const node=e.target.closest('.room-chat-message');if(!node)return;e.preventDefault();openRoomMessageActions(node)});host.addEventListener('click',e=>{if(roomMessageSuppressClick){roomMessageSuppressClick=false;e.preventDefault();e.stopPropagation();return}const node=e.target.closest('.room-chat-message');if(!e.target.closest('.room-message-tools'))closeRoomMessageActions(node)});host.addEventListener('keydown',e=>{const node=e.target.closest('.room-chat-message');if(!node)return;if((e.key==='Enter'||e.key===' ')&&e.target===node){e.preventDefault();node.classList.contains('is-actions-open')?closeRoomMessageActions():openRoomMessageActions(node)}if(e.key==='Escape')closeRoomMessageActions()});document.addEventListener('click',e=>{if(!e.target.closest('#roomChatMessages'))closeRoomMessageActions()});}

function findRoomMessage(id){return roomMessages.find(x=>x.id===id)||roomPinnedMessages.find(x=>x.id===id)}
function setRoomReply(id){const m=findRoomMessage(id);if(!m)return;roomReplyTarget=m;const bar=$('roomReplyBar');if(bar){bar.hidden=false;bar.innerHTML=`<span><strong>Replying to ${esc(profileName(roomProfiles.get(String(m.sender_id))||{}))}</strong><small>${esc(m.body.slice(0,140))}</small></span><button type="button" id="cancelRoomReply" aria-label="Cancel reply">×</button>`}const input=$('roomChatInput');if(input){input.placeholder='Write a reply…';input.focus()}}
async function copyRoomMessage(id){const m=findRoomMessage(id);if(!m)return;try{await navigator.clipboard.writeText(m.body);notice('Message copied.','success')}catch(_){notice('Clipboard access is unavailable in this browser.','error')}}
async function toggleRoomPin(id,pin){try{const r=await db.rpc('spike_room_toggle_pin',{p_message_id:id,p_pin:pin});if(r.error)throw r.error;await refreshRoomMessages();if($('roomPinnedOnly')?.checked)await loadPinnedRoomMessages();await roomChannel?.send({type:'broadcast',event:'room_message_update',payload:{message_id:id}});notice(pin?'Message pinned.':'Message unpinned.','success')}catch(e){notice(e.message||'Could not update the pinned message. Apply the latest Rooms migration.','error')}}
function reportRoomMessage(id){if(!findRoomMessage(id))return;roomReportingMessageId=id;$('roomMessageReportDetails').value='';$('roomMessageReportError').hidden=true;showOverlay('roomMessageReportOverlay',true)}
async function submitRoomMessageReport(e){e.preventDefault();const error=$('roomMessageReportError'),button=$('roomMessageReportForm')?.querySelector('button[type=submit]');if(!roomReportingMessageId)return;error.hidden=true;if(button)button.disabled=true;try{const r=await db.rpc('spike_room_report_message',{p_message_id:roomReportingMessageId,p_reason:$('roomMessageReportReason').value,p_details:$('roomMessageReportDetails').value.trim()});if(r.error)throw r.error;showOverlay('roomMessageReportOverlay',false);roomReportingMessageId=null;notice('Message report submitted for review.','success')}catch(e){error.textContent=e.message||'Could not submit this report.';error.hidden=false}finally{if(button)button.disabled=false}}
async function refreshRoomMessages(){if(!room?.id)return;const rows=await fetchRoomMessages();roomHasOlderMessages=rows.length===60;roomMessages=rows.reverse();await loadRoomReactions();await loadRoomPaidRewards();const missing=roomMessages.map(m=>m.sender_id).filter(id=>!roomProfiles.has(String(id)));const extra=await getProfiles(missing);extra.forEach((v,k)=>roomProfiles.set(k,v));renderRoomMessages(false)}
function editRoomMessage(id){const m=findRoomMessage(id);if(!m||m.sender_id!==me.id)return;const form=$('roomMessageEditForm'),input=$('roomMessageEditInput');if(!form||!input){notice('Message editing is unavailable in this version.','error');return}form.dataset.messageId=id;input.value=m.body;showOverlay('roomMessageEditOverlay',true);setTimeout(()=>input.focus(),40)}
async function submitRoomMessageEdit(e){e.preventDefault();const form=$('roomMessageEditForm'),input=$('roomMessageEditInput'),id=form?.dataset.messageId,body=input?.value.trim(),button=form?.querySelector('button[type="submit"]');if(!id||!body||body.length>800){notice('Messages must contain 1–800 characters.','error');return}if(button)button.disabled=true;try{const r=await db.rpc('spike_room_edit_message',{p_message_id:id,p_body:body});if(r.error)throw r.error;showOverlay('roomMessageEditOverlay',false);await refreshRoomMessages();if($('roomPinnedOnly')?.checked)await loadPinnedRoomMessages();try{await roomChannel?.send({type:'broadcast',event:'room_message_update',payload:{message_id:id}})}catch(_){}notice('Message updated.','success')}catch(e){notice(e.message||'Could not edit this message. Apply the latest SPIKE Rooms database migration and try again.','error')}finally{if(button)button.disabled=false}}
async function deleteRoomMessage(id){const m=findRoomMessage(id);if(!m||!(m.sender_id===me.id||isModerator()))return;const accepted=await ask({title:'Delete this message?',message:'This message will be removed from the room conversation.',confirmText:'Delete message',cancelText:'Keep message',danger:true,kicker:'ROOM CHAT'});if(accepted!==true)return;try{const r=await db.rpc('spike_room_delete_message',{p_message_id:id});if(r.error)throw r.error;roomMessages=roomMessages.filter(x=>x.id!==id);roomPinnedMessages=roomPinnedMessages.filter(x=>x.id!==id);roomReactions=roomReactions.filter(x=>x.message_id!==id);roomPaidRewards=roomPaidRewards.filter(x=>x.message_id!==id);renderRoomMessages(false);try{await roomChannel?.send({type:'broadcast',event:'room_message_update',payload:{message_id:id,deleted:true}})}catch(_){}notice('Message deleted.','success')}catch(e){notice(e.message||'Could not delete this message. Apply the latest SPIKE Rooms database migration and try again.','error')}}
async function toggleRoomReaction(id,reaction){if(!findRoomMessage(id)||!['👍','❤️','😂','🔥','👏'].includes(reaction))return;try{const r=await db.rpc('spike_room_react_message',{p_message_id:id,p_reaction:reaction});if(r.error)throw r.error;await loadRoomReactions();renderRoomMessages(false);try{await roomChannel?.send({type:'broadcast',event:'room_reaction',payload:{message_id:id}})}catch(_){} }catch(e){notice(e.message||'Reactions are not available yet. Apply the latest SPIKE Rooms database migration.','error')}}
function roomRequestId(){return window.crypto?.randomUUID?window.crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function openRoomPaidComment(id){const m=findRoomMessage(id);if(!m||m.sender_id===me.id)return notice('Choose another member’s message.','warning');const form=$('roomPaidCommentForm');if(!form)return notice('Paid comments are unavailable. Refresh and try again.','error');form.dataset.targetMessageId=id;form.dataset.requestId=roomRequestId();const p=roomProfiles.get(String(m.sender_id))||{};say('roomPaidCommentRecipient',profileName(p));const input=$('roomPaidCommentInput');if(input)input.value='';const amount=$('roomPaidCommentAmount');if(amount)amount.value='2';showOverlay('roomPaidCommentOverlay',true);setTimeout(()=>input?.focus(),60)}
async function sendRoomPaidReward(targetId,kind,code,comment,requestId,button){if(!targetId||!requestId)return;const m=findRoomMessage(targetId);if(!m||m.sender_id===me.id)throw new Error('Choose another member’s message');if(button)button.disabled=true;try{const r=await db.rpc('spike_room_reward_message',{p_target_message_id:targetId,p_reward_kind:kind,p_reward_code:code,p_comment:comment||null,p_request_id:requestId});if(r.error)throw r.error;const data=r.data||{};if(kind==='comment'&&data.comment_message?.id){const msg=data.comment_message;if(!roomMessages.some(x=>x.id===msg.id)){roomMessages.push(msg);roomMessages.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at))}roomProfiles.set(String(me.id),profile);renderRoomMessages();try{await roomChannel?.send({type:'broadcast',event:'room_message',payload:{message:msg}})}catch(_){}}await loadRoomPaidRewards();renderRoomMessages(false);try{await roomChannel?.send({type:'broadcast',event:'room_paid_reward',payload:{message_id:targetId,kind,reward_code:code,comment_message:data.comment_message||null}})}catch(_){}notice(`${kind==='reaction'?'Paid reaction':'Paid comment'} sent · ${Number(data.coin_cost||0)} SP COINS.`,'success');return data}catch(e){if(button)button.disabled=false;throw e}}
async function sendRoomPaidReaction(button){const targetId=button?.dataset.messageId,code=button?.dataset.messagePaidReaction,cost=Number(button?.dataset.rewardCost||0);if(!targetId||!code||!cost||button.disabled)return;const accepted=await ask({title:'Send paid reaction?',message:`Send this reaction for ${cost} SP COINS?`,confirmText:`Send · ${cost} SP COINS`,cancelText:'Cancel',kicker:'SPIKE ROOM'});if(accepted!==true)return;button.dataset.requestId=button.dataset.requestId||roomRequestId();try{await sendRoomPaidReward(targetId,'reaction',code,null,button.dataset.requestId,button);button.dataset.requestId=''}catch(e){notice(e.message||'Could not send this reaction. Your SP COINS were not charged unless the transaction completed.','error')}}
async function submitRoomPaidComment(e){e.preventDefault();const form=$('roomPaidCommentForm'),input=$('roomPaidCommentInput'),amount=Number($('roomPaidCommentAmount')?.value||0),button=form?.querySelector('button[type=submit]'),targetId=form?.dataset.targetMessageId,body=String(input?.value||'').trim();if(!targetId||!body||body.length>500||![2,3,5].includes(amount)){notice('Write a comment and choose a valid reward amount.','warning');return}const code=amount===2?'quick_2':amount===3?'standard_3':'special_5';const accepted=await ask({title:'Send paid comment?',message:`Send this comment for ${amount} SP COINS?`,confirmText:`Send · ${amount} SP COINS`,cancelText:'Cancel',kicker:'SPIKE ROOM'});if(accepted!==true)return;form.dataset.requestId=form.dataset.requestId||roomRequestId();if(button)button.disabled=true;try{await sendRoomPaidReward(targetId,'comment',code,body,form.dataset.requestId,button);form.dataset.requestId='';form.dataset.targetMessageId='';showOverlay('roomPaidCommentOverlay',false)}catch(err){notice(err.message||'Could not send this comment. Your SP COINS were not charged unless the transaction completed.','error')}finally{if(button)button.disabled=false}}
async function sendRoomMessage(e){e.preventDefault();const input=$('roomChatInput'),form=$('roomChatForm'),button=form?.querySelector('button'),body=input?.value.trim();if(!body||!room?.allow_chat||room.status!=='live'||!button)return;button.disabled=true;const original=button.innerHTML;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>';try{const r=roomReplyTarget?await db.rpc('spike_room_send_reply',{p_room_id:room.id,p_body:body,p_reply_to_message_id:roomReplyTarget.id}):await db.rpc('spike_room_send_message',{p_room_id:room.id,p_body:body});if(r.error)throw r.error;const m=Array.isArray(r.data)?r.data[0]:r.data;if(m?.id&&!roomMessages.some(x=>x.id===m.id)){roomMessages.push(m);roomProfiles.set(String(me.id),profile);roomMessages.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));renderRoomMessages()}input.value='';roomReplyTarget=null;const bar=$('roomReplyBar');if(bar)bar.hidden=true;input.placeholder='Write a message…';setStatus('Message sent.');if(roomChannel&&m?.id){try{await roomChannel.send({type:'broadcast',event:'room_message',payload:{message:m}})}catch(broadcastError){console.info('[SPIKE Rooms] Message saved; live broadcast will recover on sync:',broadcastError?.message)}}}catch(err){setStatus(err.message||'Message could not be sent. Your draft is still here.',true);notice(err.message||'Message could not be sent. Your draft is still here.','error')}finally{button.disabled=false;button.innerHTML=original;input.focus()}}
function pruneVoicePeersForPresence(){if(!isHost())return;const online=roomOnlineIds();voiceHostPeers.forEach((pc,id)=>{if(!online.has(String(id))){try{pc.close()}catch(_){}voiceHostPeers.delete(id)}});voiceHostSpeakerPeers.forEach((pc,id)=>{if(!online.has(String(id))){try{pc.close()}catch(_){}voiceHostSpeakerPeers.delete(id);try{voiceMixSources.get(id)?.disconnect()}catch(_){}voiceMixSources.delete(id)}});voiceUI()}
async function connectRoomChannel(id){roomPresenceReady=false;roomPresenceConnected=false;if(roomChannel)try{await db.removeChannel(roomChannel)}catch(_){}roomChannel=db.channel('spike-room:'+id,{config:{private:true,presence:{key:me.id}}}).on('broadcast',{event:'room_message'},payload=>{const m=payload.payload?.message;if(m?.id&&!roomMessages.some(x=>x.id===m.id)){roomMessages.push(m);roomMessages.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(!roomProfiles.has(String(m.sender_id)))getProfiles([m.sender_id]).then(p=>p.forEach((v,k)=>roomProfiles.set(k,v))).then(()=>renderRoomMessages());else renderRoomMessages()}}).on('broadcast',{event:'room_gift'},payload=>{const g=payload.payload||{};if(g.reference){showGiftCelebration(g);notice(`${g.gift_icon||'🎁'} ${g.sender_name||'A member'} sent ${g.gift_name||'a gift'} to ${g.receiver_name||'a room member'}.`,'success');void loadRoomGiftFeed()}}).on('broadcast',{event:'room_message_update'},()=>refreshRoomMessages().catch(e=>console.warn('[SPIKE Rooms] message sync:',e.message))).on('broadcast',{event:'room_reaction'},()=>{loadRoomReactions().then(()=>renderRoomMessages(false)).catch(()=>{})}).on('broadcast',{event:'room_paid_reward'},payload=>{const p=payload.payload||{};if(p.comment_message?.id&&!roomMessages.some(x=>x.id===p.comment_message.id)){roomMessages.push(p.comment_message);roomMessages.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(!roomProfiles.has(String(p.comment_message.sender_id)))getProfiles([p.comment_message.sender_id]).then(rows=>rows.forEach((v,k)=>roomProfiles.set(k,v))).then(()=>renderRoomMessages());else renderRoomMessages()}loadRoomPaidRewards().then(()=>renderRoomMessages(false)).catch(()=>{})}).on('broadcast',{event:'room_typing'},payload=>{const p=payload.payload||{};if(p.user_id&&p.user_id!==me.id){const n=$('roomTypingStatus');if(n){n.textContent=(p.display_name||'Someone')+' is typing…';n.hidden=false;clearTimeout(roomTypingHideTimer);roomTypingHideTimer=setTimeout(()=>{n.hidden=true},1800)}}}).on('broadcast',{event:'room_state'},async()=>{try{await refreshRoomState();await refreshRoomMembers()}catch(e){console.warn('[SPIKE Rooms] room state refresh:',e.message)}}).on('broadcast',{event:'room_voice_signal'},payload=>{handleVoiceSignal(payload.payload||{}).catch(e=>console.warn('[SPIKE voice] signal:',e.message))}).on('presence',{event:'sync'},()=>{roomPresenceReady=true;roomPresenceConnected=true;pruneVoicePeersForPresence();renderStage()}).on('presence',{event:'join'},()=>{roomPresenceReady=true;roomPresenceConnected=true;renderStage()}).on('presence',{event:'leave'},()=>{roomPresenceReady=true;roomPresenceConnected=true;pruneVoicePeersForPresence();renderStage()}).subscribe(async status=>{if(status==='SUBSCRIBED'){roomPresenceReady=true;roomPresenceConnected=true;try{await roomChannel.track({user_id:me.id,display_name:profileName(profile),joined_at:new Date().toISOString()});renderStage();await roomChannel.send({type:'broadcast',event:'room_state',payload:{type:'member_joined'}})}catch(e){roomPresenceConnected=false;renderStage();console.info('[SPIKE Rooms] presence tracking unavailable:',e.message)}}else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){roomPresenceConnected=false;renderStage();setStatus('Room updates interrupted. Reconnecting…',true)}else if(status==='CLOSED'){roomPresenceConnected=false;renderStage()}})}
function voiceMemberAllowed(id){return roomMembers.some(m=>String(m.user_id)===String(id)&&m.member_state==='active')}
function voiceUI(){const host=isHost(),start=$('startVoiceBroadcast'),stop=$('stopVoiceBroadcast'),hostMic=$('toggleHostMic'),listen=$('listenToVoice'),mute=$('muteRoomAudio'),record=$('recordRoomAudio'),stopRecord=$('stopRecordRoomAudio'),recordConsent=$('allowRoomRecording'),indicator=$('roomAudioIndicator'),title=$('roomAudioTitle'),status=$('roomAudioStatus');if(start)start.hidden=!host||room?.status!=='live'||voiceBroadcasting;if(stop)stop.hidden=!host||!voiceBroadcasting;if(hostMic){hostMic.hidden=!host||!voiceBroadcasting;const enabled=!!voiceLocalStream?.getAudioTracks().some(t=>t.enabled);hostMic.innerHTML=enabled?'<i class="fa-solid fa-microphone"></i> Mute microphone':'<i class="fa-solid fa-microphone-slash"></i> Unmute microphone'}if(listen)listen.hidden=host||room?.status!=='live'||!!voiceListenerPc&&!$('roomRemoteAudio')?.paused;if(mute)mute.hidden=!voiceListenerPc;if(recordConsent){recordConsent.hidden=!host||!voiceBroadcasting;recordConsent.textContent=voiceRecordingAllowed?'Disable listener recording':'Allow listener recording';recordConsent.classList.toggle('is-enabled',voiceRecordingAllowed)}if(record)record.hidden=!voiceRemoteStream||!!voiceRecorder||!voiceRecordingAllowed;if(stopRecord)stopRecord.hidden=!voiceRecorder;const mine=roomMembers.find(m=>m.user_id===me?.id&&m.member_state==='active');const joinStage=$('joinStageAudio'),leaveStage=$('leaveStageAudio');if(joinStage)joinStage.hidden=!(mine?.role==='speaker'&&!mine?.is_muted&&voiceRemoteActive&&!voiceSpeakerPc);if(leaveStage)leaveStage.hidden=!voiceSpeakerPc;if(indicator)indicator.classList.toggle('is-live',voiceBroadcasting||voiceRemoteActive);if(title)title.textContent=voiceBroadcasting?'You are live':voiceRemoteActive?'Live voice is on':'Live voice is ready';if(status)status.textContent=voiceBroadcasting?`${voiceHostPeers.size} listener connection${voiceHostPeers.size===1?'':'s'} · ${voiceHostSpeakerPeers.size} additional speaker${voiceHostSpeakerPeers.size===1?'':'s'}`:voiceRemoteActive?voiceListenerPc?'Connected to the live broadcast':'Tap Listen live to hear the host':'The host can start a live audio broadcast.'}
function voicePeerTopic(target){const pair=[String(me.id),String(target)].sort();return 'spike-room-voice:'+room.id+':'+pair[0]+':'+pair[1]}
async function getVoicePeerChannel(target){target=String(target||'');if(!uuidRE.test(target)||target===String(me?.id||''))throw new Error('Invalid room voice peer.');const topic=voicePeerTopic(target);if(voicePeerChannels.has(topic))return await voicePeerChannels.get(topic);const ch=db.channel(topic,{config:{private:true,broadcast:{ack:true,self:false}}});ch.on('broadcast',{event:'room_voice_signal'},ev=>{handleVoiceSignal(ev?.payload||{}).catch(e=>console.warn('[SPIKE voice] peer signal:',e.message))});const promise=new Promise((resolve,reject)=>{let settled=false;const timer=setTimeout(()=>{if(!settled){settled=true;reject(new Error('Private voice signaling channel timed out. Check the latest SPIKE Rooms migration and Supabase Realtime access.'))}},12000);ch.subscribe(status=>{if(status==='SUBSCRIBED'&&!settled){settled=true;clearTimeout(timer);resolve(ch)}else if(['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(status)&&!settled){settled=true;clearTimeout(timer);reject(new Error('Private voice signaling channel failed ('+status+').'))}})});voicePeerChannels.set(topic,promise);try{return await promise}catch(e){voicePeerChannels.delete(topic);try{await db.removeChannel(ch)}catch(_){}throw e}}
async function syncVoicePeerChannels(){if(!room?.id||!me?.id)return;const targets=isHost()?roomMembers.filter(m=>m.member_state==='active'&&m.user_id!==me.id).map(m=>m.user_id):[room?.active_host_id||room?.host_id];const clean=[...new Set(targets.filter(id=>uuidRE.test(String(id||''))&&String(id)!==String(me.id)))];const wanted=new Set(clean.map(voicePeerTopic));for(const [topic,promise] of [...voicePeerChannels])if(!wanted.has(topic)){voicePeerChannels.delete(topic);try{const ch=await promise;await db.removeChannel(ch)}catch(_){}}await Promise.all(clean.map(id=>getVoicePeerChannel(id).catch(e=>console.info('[SPIKE voice] private peer channel unavailable:',e.message))))}
async function voiceSignal(payload){if(!roomChannel||!room?.id)return;const message={...payload,from:me.id,room_id:room.id};if(payload?.to){const ch=await getVoicePeerChannel(payload.to);const result=await ch.send({type:'broadcast',event:'room_voice_signal',payload:message});if(result==='error')throw new Error('Private voice signal could not be delivered.');return result}return roomChannel.send({type:'broadcast',event:'room_voice_signal',payload:message})}
function isDirectRoomIceCandidate(candidate){const value=typeof candidate==='string'?candidate:candidate?.candidate;return !/\btyp\s+relay\b/i.test(String(value||''))}
function directRoomDescription(description){if(!description||typeof description.sdp!=='string')return description;return {...description,sdp:description.sdp.replace(/^a=candidate:[^\r\n]*\btyp\s+relay\b[^\r\n]*(?:\r?\n)?/gim,'')}}
function newPeerConfig(){return {iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun.cloudflare.com:3478'}],iceTransportPolicy:'all',bundlePolicy:'max-bundle',rtcpMuxPolicy:'require',iceCandidatePoolSize:2}}
async function startVoiceBroadcast(){if(!isHost()||room?.status!=='live')return notice('Only the active host can start voice in a live room.','warning');if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)return notice('This browser does not support live microphone audio.','error');const button=$('startVoiceBroadcast');if(button)button.disabled=true;try{voiceLocalStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});const AudioContextCtor=window.AudioContext||window.webkitAudioContext;if(AudioContextCtor){try{voiceMixContext=new AudioContextCtor();await voiceMixContext.resume();voiceMixDestination=voiceMixContext.createMediaStreamDestination();voiceMixContext.createMediaStreamSource(voiceLocalStream).connect(voiceMixDestination)}catch(mixError){console.info('[SPIKE voice] Audio mixing unavailable; host-only audio remains active:',mixError.message);voiceMixDestination=null}}voiceBroadcasting=true;voiceMuted=false;voiceRecordingAllowed=false;await voiceSignal({kind:'voice_state',active:true,recording_allowed:false});voiceUI();notice('Your live voice broadcast has started.','success')}catch(e){voiceBroadcasting=false;voiceLocalStream?.getTracks().forEach(t=>t.stop());voiceLocalStream=null;voiceUI();notice(e.name==='NotAllowedError'?'Allow microphone access in your browser to go live.':e.message||'Could not start the microphone.','error')}finally{if(button)button.disabled=false}}
async function createHostPeer(listenerId){if(!voiceBroadcasting||!voiceLocalStream||!voiceMemberAllowed(listenerId)||listenerId===me.id)return;if(!voiceHostPeers.has(listenerId)&&voiceHostPeers.size>=VOICE_DIRECT_PEER_LIMIT){await voiceSignal({kind:'voice_full',to:listenerId,limit:VOICE_DIRECT_PEER_LIMIT});return}let pc=voiceHostPeers.get(listenerId);if(pc){try{pc.close()}catch(_){}}pc=new RTCPeerConnection(newPeerConfig());voiceHostPeers.set(listenerId,pc);voicePendingIce.set(listenerId,[]);const outbound=voiceMixDestination?.stream||voiceLocalStream;outbound.getTracks().forEach(track=>pc.addTrack(track,outbound));pc.onicecandidate=e=>{if(e.candidate&&isDirectRoomIceCandidate(e.candidate))voiceSignal({kind:'ice',to:listenerId,candidate:e.candidate.toJSON(),side:'host'}).catch(()=>{})};let peerDisconnectTimer=null;pc.onconnectionstatechange=()=>{const state=pc.connectionState;if(state==='connected'){if(peerDisconnectTimer){clearTimeout(peerDisconnectTimer);peerDisconnectTimer=null;}voiceUI();return;}if(state==='disconnected'){if(peerDisconnectTimer)clearTimeout(peerDisconnectTimer);peerDisconnectTimer=setTimeout(()=>{if(pc.connectionState==='disconnected'||pc.connectionState==='failed'){if(voiceHostPeers.get(listenerId)===pc)voiceHostPeers.delete(listenerId);try{pc.close()}catch(_){}voiceUI();}},15000);return;}if(state==='failed'||state==='closed'){if(peerDisconnectTimer)clearTimeout(peerDisconnectTimer);if(voiceHostPeers.get(listenerId)===pc)voiceHostPeers.delete(listenerId);try{if(state!=='closed')pc.close()}catch(_){}voiceUI();}};const offer=await pc.createOffer();await pc.setLocalDescription(offer);await voiceSignal({kind:'offer',to:listenerId,description:pc.localDescription,side:'host'});voiceUI()}
async function closeStageSpeaker(){if(voiceSpeakerPc&&roomChannel)voiceSignal({kind:'speaker_leave',to:room?.active_host_id||room?.host_id}).catch(()=>{});try{voiceSpeakerPc?.close()}catch(_){}voiceSpeakerPc=null;voiceSpeakerStream?.getTracks().forEach(t=>t.stop());voiceSpeakerStream=null;voiceSpeakerPendingIce=[];voiceUI()}
async function joinStageAudio(){const mine=roomMembers.find(m=>m.user_id===me.id&&m.member_state==='active');if(!mine||mine.role!=='speaker')return notice('The host must approve you as a speaker first.','warning');if(mine.is_muted)return notice('The host has muted your microphone on stage.','warning');if(!voiceRemoteActive)return notice('Listen to the live broadcast first, then join the stage.','warning');if(!window.RTCPeerConnection||!navigator.mediaDevices?.getUserMedia)return notice('This browser does not support stage audio.','error');if(voiceSpeakerPc)return;const b=$('joinStageAudio');if(b)b.disabled=true;try{await listenToVoice();voiceSpeakerStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});voiceSpeakerPc=new RTCPeerConnection(newPeerConfig());voiceSpeakerStream.getTracks().forEach(t=>voiceSpeakerPc.addTrack(t,voiceSpeakerStream));voiceSpeakerPc.onicecandidate=e=>{if(e.candidate&&isDirectRoomIceCandidate(e.candidate))voiceSignal({kind:'speaker_ice',to:room?.active_host_id||room?.host_id,candidate:e.candidate.toJSON()}).catch(()=>{})};const stagePc=voiceSpeakerPc;let stageDisconnectTimer=null;stagePc.onconnectionstatechange=()=>{const state=stagePc.connectionState;if(state==='connected'){if(stageDisconnectTimer){clearTimeout(stageDisconnectTimer);stageDisconnectTimer=null;}voiceUI();return;}if(state==='disconnected'){if(stageDisconnectTimer)clearTimeout(stageDisconnectTimer);stageDisconnectTimer=setTimeout(()=>{if(stagePc.connectionState==='disconnected'||stagePc.connectionState==='failed'){if(voiceSpeakerPc===stagePc)void closeStageSpeaker();notice('Your stage connection was interrupted. Try joining again.','warning');}},15000);voiceUI();return;}if(state==='failed'||state==='closed'){if(stageDisconnectTimer)clearTimeout(stageDisconnectTimer);if(voiceSpeakerPc===stagePc){void closeStageSpeaker();if(state==='failed')notice('Your stage connection was interrupted. Try joining again.','warning');}}else voiceUI()};const offer=await voiceSpeakerPc.createOffer();await voiceSpeakerPc.setLocalDescription(offer);await voiceSignal({kind:'speaker_offer',to:room?.active_host_id||room?.host_id,description:voiceSpeakerPc.localDescription});voiceUI();notice('Joining the stage…','info')}catch(e){await closeStageSpeaker();notice(e.name==='NotAllowedError'?'Allow microphone access to join the stage.':e.message||'Could not join the stage.','error')}finally{if(b)b.disabled=false}}
async function acceptSpeakerOffer(payload,sender){if(!isHost()||!voiceBroadcasting)return;if(!voiceMixDestination||!voiceMixContext){await voiceSignal({kind:'speaker_unavailable',to:sender});return}const member=roomMembers.find(m=>String(m.user_id)===sender&&m.member_state==='active'&&m.role==='speaker');if(!member)return;if(member.is_muted){await voiceSignal({kind:'speaker_muted',to:sender});return}if(!voiceHostSpeakerPeers.has(sender)&&voiceHostSpeakerPeers.size>=VOICE_SPEAKER_LIMIT){await voiceSignal({kind:'speaker_full',to:sender,limit:VOICE_SPEAKER_LIMIT});return}try{const old=voiceHostSpeakerPeers.get(sender);if(old)old.close();const pc=new RTCPeerConnection(newPeerConfig());voiceHostSpeakerPeers.set(sender,pc);voiceHostSpeakerIce.set(sender,[]);pc.ontrack=e=>{const stream=e.streams?.[0]||new MediaStream([e.track]);try{voiceMixSources.get(sender)?.disconnect()}catch(_){}try{const source=voiceMixContext.createMediaStreamSource(stream);if(!member.is_muted){source.connect(voiceMixDestination);source.__spikeConnected=true}voiceMixSources.set(sender,source)}catch(err){console.warn('[SPIKE voice] Could not mix speaker audio:',err.message)}};pc.onicecandidate=e=>{if(e.candidate&&isDirectRoomIceCandidate(e.candidate))voiceSignal({kind:'speaker_host_ice',to:sender,candidate:e.candidate.toJSON()}).catch(()=>{})};let speakerDisconnectTimer=null;pc.onconnectionstatechange=()=>{const state=pc.connectionState;if(state==='connected'){if(speakerDisconnectTimer){clearTimeout(speakerDisconnectTimer);speakerDisconnectTimer=null;}voiceUI();return;}if(state==='disconnected'){if(speakerDisconnectTimer)clearTimeout(speakerDisconnectTimer);speakerDisconnectTimer=setTimeout(()=>{if(pc.connectionState==='disconnected'||pc.connectionState==='failed'){try{voiceMixSources.get(sender)?.disconnect()}catch(_){}voiceMixSources.delete(sender);if(voiceHostSpeakerPeers.get(sender)===pc)voiceHostSpeakerPeers.delete(sender);try{pc.close()}catch(_){}voiceUI();}},15000);return;}if(state==='failed'||state==='closed'){if(speakerDisconnectTimer)clearTimeout(speakerDisconnectTimer);try{voiceMixSources.get(sender)?.disconnect()}catch(_){}voiceMixSources.delete(sender);if(voiceHostSpeakerPeers.get(sender)===pc)voiceHostSpeakerPeers.delete(sender);try{if(state!=='closed')pc.close()}catch(_){}voiceUI();}};await pc.setRemoteDescription(directRoomDescription(payload.description));const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await voiceSignal({kind:'speaker_answer',to:sender,description:pc.localDescription});for(const c of voiceHostSpeakerIce.get(sender)||[])await pc.addIceCandidate(c).catch(()=>{});voiceHostSpeakerIce.delete(sender);voiceUI()}catch(e){console.warn('[SPIKE voice] speaker setup failed:',e.message);try{voiceHostSpeakerPeers.get(sender)?.close()}catch(_){}voiceHostSpeakerPeers.delete(sender)}}
async function listenToVoice(){if(!window.RTCPeerConnection)return notice('This browser does not support live audio.','error');const audio=$('roomRemoteAudio');if(voiceListenerPc&&voiceRemoteStream&&audio){try{audio.muted=false;await audio.play();voiceUI();return}catch(e){notice('Tap Listen live again to allow audio playback.','warning');return}}try{voiceRemoteActive=true;voiceUI();await voiceSignal({kind:'join',to:room?.active_host_id||room?.host_id});setStatus('Connecting to live voice…')}catch(e){notice(e.message||'Could not connect to live voice.','error')}}
async function handleVoiceSignal(payload){
 if(!payload||payload.room_id!==room?.id||payload.from===me.id||!voiceMemberAllowed(payload.from))return;
 const sender=String(payload.from),hostId=String(room?.active_host_id||room?.host_id||'');
 if(payload.to&&payload.to!==me.id)return;
 if(payload.kind==='voice_full'){if(payload.to===me.id){voiceRemoteActive=false;voiceUI();notice('This room has reached its direct-audio listener capacity.','warning')}return}
 if(payload.kind==='speaker_full'){if(payload.to===me.id){void closeStageSpeaker();notice('The stage is full. The host can have up to four additional speakers.','warning')}return}
 if(payload.kind==='speaker_unavailable'){if(payload.to===me.id){void closeStageSpeaker();notice('This browser or host device cannot mix multiple microphones. You can still listen to the room.','warning')}return}
 if(payload.kind==='speaker_muted'){if(payload.to===me.id){void closeStageSpeaker();notice('The host has muted your microphone on stage.','warning')}return}
 if(payload.kind==='voice_state'){if(sender!==hostId)return;voiceRemoteActive=!!payload.active;voiceRecordingAllowed=!!payload.active&&payload.recording_allowed===true;if(!voiceRecordingAllowed&&voiceRecorder&&voiceRecorder.state!=='inactive')stopRoomRecording();if(!voiceRemoteActive){closeListenerPeer();void closeStageSpeaker();voiceHostPeers.forEach(pc=>pc.close());voiceHostPeers.clear()}voiceUI();return}
 if(payload.kind==='join'){if(!isHost()||!voiceBroadcasting||sender===me.id)return;try{await createHostPeer(sender)}catch(e){console.warn('[SPIKE voice] host peer setup:',e.message)}return}
 if(payload.kind==='speaker_offer'){if(!isHost()||sender!==String(payload.from))return;await acceptSpeakerOffer(payload,sender);return}
 if(payload.kind==='speaker_leave'&&isHost()){try{voiceHostSpeakerPeers.get(sender)?.close()}catch(_){}voiceHostSpeakerPeers.delete(sender);voiceHostSpeakerIce.delete(sender);try{voiceMixSources.get(sender)?.disconnect()}catch(_){}voiceMixSources.delete(sender);voiceUI();return}
 if(payload.kind==='speaker_answer'&&!isHost()&&sender===hostId){if(voiceSpeakerPc&&voiceSpeakerPc.signalingState==='have-local-offer')try{await voiceSpeakerPc.setRemoteDescription(directRoomDescription(payload.description));for(const c of voiceSpeakerPendingIce.splice(0))await voiceSpeakerPc.addIceCandidate(c).catch(()=>{})}catch(e){console.warn('[SPIKE voice] speaker answer:',e.message)}return}
 if(payload.kind==='speaker_ice'&&isDirectRoomIceCandidate(payload.candidate)&&isHost()){const pc=voiceHostSpeakerPeers.get(sender);if(pc?.remoteDescription)await pc.addIceCandidate(payload.candidate).catch(()=>{});else{const q=voiceHostSpeakerIce.get(sender)||[];q.push(payload.candidate);voiceHostSpeakerIce.set(sender,q)}return}
 if(payload.kind==='speaker_host_ice'&&isDirectRoomIceCandidate(payload.candidate)&&!isHost()&&sender===hostId){if(voiceSpeakerPc?.remoteDescription)await voiceSpeakerPc.addIceCandidate(payload.candidate).catch(()=>{});else voiceSpeakerPendingIce.push(payload.candidate);return}
 if(payload.kind==='offer'){if(sender!==hostId)return;try{voiceRemoteActive=true;closeListenerPeer();voiceListenerPc=new RTCPeerConnection(newPeerConfig());voiceRemoteStream=new MediaStream();voiceListenerPc.onconnectionstatechange=()=>{const state=voiceListenerPc?.connectionState;if(['failed','closed'].includes(state)){closeListenerPeer();if(state==='failed')notice('The live audio connection was lost. Check your network and try listening again.','warning')}else voiceUI()};voiceListenerPc.ontrack=e=>{(e.streams?.[0]?.getTracks()||[e.track]).forEach(t=>{if(!voiceRemoteStream.getTracks().some(x=>x.id===t.id))voiceRemoteStream.addTrack(t)});const audio=$('roomRemoteAudio');if(audio){audio.srcObject=voiceRemoteStream;audio.play().catch(()=>setStatus('Tap Listen live again to allow audio playback.'))}voiceUI()};voiceListenerPc.onicecandidate=e=>{if(e.candidate&&isDirectRoomIceCandidate(e.candidate))voiceSignal({kind:'ice',to:sender,candidate:e.candidate.toJSON(),side:'listener'}).catch(()=>{})};await voiceListenerPc.setRemoteDescription(directRoomDescription(payload.description));const answer=await voiceListenerPc.createAnswer();await voiceListenerPc.setLocalDescription(answer);await voiceSignal({kind:'answer',to:sender,description:voiceListenerPc.localDescription});const pending=voicePendingIce.get(sender)||[];for(const c of pending)await voiceListenerPc.addIceCandidate(c).catch(()=>{});voicePendingIce.delete(sender);voiceUI()}catch(e){console.warn('[SPIKE voice] listener setup:',e.message);closeListenerPeer();notice('Could not connect to the host audio. The network may not allow a direct peer connection.','warning')}return}
 if(payload.kind==='answer'&&isHost()){const pc=voiceHostPeers.get(sender);if(pc&&pc.signalingState==='have-local-offer')try{await pc.setRemoteDescription(directRoomDescription(payload.description));const pending=voicePendingIce.get(sender)||[];for(const c of pending)await pc.addIceCandidate(c).catch(()=>{});voicePendingIce.delete(sender)}catch(e){console.warn('[SPIKE voice] answer:',e.message)}return}
 if(payload.kind==='ice'&&payload.candidate&&isDirectRoomIceCandidate(payload.candidate)){if(isHost()){const pc=voiceHostPeers.get(sender);if(pc?.remoteDescription)await pc.addIceCandidate(payload.candidate).catch(()=>{});else{const q=voicePendingIce.get(sender)||[];q.push(payload.candidate);voicePendingIce.set(sender,q)}}else if(sender===hostId){if(voiceListenerPc?.remoteDescription)await voiceListenerPc.addIceCandidate(payload.candidate).catch(()=>{});else{const q=voicePendingIce.get(sender)||[];q.push(payload.candidate);voicePendingIce.set(sender,q)}}}
}
function closeListenerPeer(){try{voiceListenerPc?.close()}catch(_){}voiceListenerPc=null;voiceRemoteStream?.getTracks().forEach(t=>t.stop());voiceRemoteStream=null;const audio=$('roomRemoteAudio');if(audio)audio.srcObject=null;voiceMuted=false;voiceUI()}
async function stopVoiceBroadcast(){if(!isHost()||!voiceBroadcasting)return;try{await voiceSignal({kind:'voice_state',active:false,recording_allowed:false})}catch(_){}voiceBroadcasting=false;voiceRecordingAllowed=false;voiceHostPeers.forEach(pc=>{try{pc.close()}catch(_){}});voiceHostPeers.clear();voicePendingIce.clear();voiceHostSpeakerPeers.forEach(pc=>{try{pc.close()}catch(_){}});voiceHostSpeakerPeers.clear();voiceMixSources.forEach(source=>{try{source.disconnect()}catch(_){}});voiceMixSources.clear();voiceHostSpeakerIce.clear();voiceMixDestination=null;if(voiceMixContext){voiceMixContext.close().catch(()=>{});voiceMixContext=null}voiceLocalStream?.getTracks().forEach(t=>t.stop());voiceLocalStream=null;voiceUI();notice('Your live broadcast has ended.','success')}
function toggleHostMicrophone(){if(!isHost()||!voiceLocalStream)return;const tracks=voiceLocalStream.getAudioTracks(),next=tracks.some(t=>t.enabled)?false:true;tracks.forEach(t=>t.enabled=next);voiceUI()}
function toggleRoomAudioMute(){const audio=$('roomRemoteAudio');if(!audio)return;audio.muted=!audio.muted;voiceMuted=audio.muted;const b=$('muteRoomAudio');if(b)b.innerHTML=audio.muted?'<i class="fa-solid fa-volume-xmark"></i> Unmute audio':'<i class="fa-solid fa-volume-high"></i> Mute audio'}
async function toggleRoomRecordingConsent(){if(!isHost()||!voiceBroadcasting)return;const next=!voiceRecordingAllowed;if(next){const ok=await ask({title:'Allow listeners to record?',message:'Listeners will be able to record the audio delivered to their devices and save it locally. You can disable recording at any time.',confirmText:'Allow recording',cancelText:'Not now',warning:true,kicker:'BROADCAST CONSENT'});if(ok!==true)return}voiceRecordingAllowed=next;try{await voiceSignal({kind:'voice_state',active:true,recording_allowed:next});voiceUI();notice(next?'Listeners may now record this broadcast.':'Listener recording has been disabled.','success')}catch(e){voiceRecordingAllowed=!next;voiceUI();notice(e.message||'Could not update recording permission.','error')}}
function startRoomRecording(){if(!voiceRecordingAllowed)return notice('The host has not enabled recording for this broadcast.','warning');if(!voiceRemoteStream||!window.MediaRecorder)return notice('Audio recording is not supported by this browser.','error');try{const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));voiceRecorder=new MediaRecorder(voiceRemoteStream,mime?{mimeType:mime}:undefined);voiceRecordedChunks=[];voiceRecorder.ondataavailable=e=>{if(e.data?.size)voiceRecordedChunks.push(e.data)};voiceRecorder.onstop=()=>{const blob=new Blob(voiceRecordedChunks,{type:voiceRecorder?.mimeType||'audio/webm'});if(!blob.size){voiceRecorder=null;voiceUI();return}const url=URL.createObjectURL(blob),a=document.createElement('a'),ext=(blob.type.includes('mp4')?'m4a':'webm');a.href=url;a.download=`SPIKE-${(room?.title||'Live-Room').replace(/[^a-z0-9-_]+/gi,'-').slice(0,40)}-${new Date().toISOString().replace(/[:.]/g,'-')}.${ext}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);voiceRecorder=null;voiceRecordedChunks=[];voiceUI();notice('Your room audio recording was saved to this device.','success')};voiceRecorder.start(1000);voiceUI();notice('Recording started. Only audio delivered to your device is recorded.','success')}catch(e){voiceRecorder=null;voiceUI();notice(e.message||'Could not start recording.','error')}}
function stopRoomRecording(){if(voiceRecorder&&voiceRecorder.state!=='inactive')voiceRecorder.stop()}
async function requestSpeaker(){try{const r=await db.rpc('spike_room_request_speaker',{p_room_id:room.id});if(r.error)throw r.error;await refreshRoomMembers();await roomChannel?.send({type:'broadcast',event:'room_state',payload:{type:'speaker_request'}});setStatus('Your request to speak has been sent.');notice('Your request to speak has been sent.','success')}catch(e){notice(e.message||'Could not request to speak.','error')}}
async function moderateMember(id,action){if(!uuidRE.test(id))return;const target=profileName(roomProfiles.get(id)||{});if(['remove','ban','transfer'].includes(action)){const title=action==='ban'?'Ban this participant?':action==='remove'?'Remove this participant?':'Transfer room hosting?';const message=action==='ban'?'They will be blocked from rejoining this room.':action==='remove'?'They will leave the room but may be able to rejoin.':'You will become a co-host and '+target+' will become the active host.';const accepted=await ask({title,message,confirmText:action==='ban'?'Ban participant':action==='remove'?'Remove participant':'Transfer host',cancelText:'Cancel',danger:action!=='transfer',warning:action==='transfer',kicker:'ROOM MODERATION'});if(accepted!==true)return}try{const r=action==='transfer'?await db.rpc('spike_room_transfer_host',{p_room_id:room.id,p_user_id:id}):await db.rpc('spike_room_moderate_member',{p_room_id:room.id,p_user_id:id,p_action:action});if(r.error)throw r.error;if(action==='transfer'){room.active_host_id=id;const mine=roomMembers.find(m=>m.user_id===me.id);if(mine)mine.role='cohost'}await refreshRoomMembers();try{await roomChannel?.send({type:'broadcast',event:'room_state',payload:{type:'member_update'}})}catch(_){}notice(action==='ban'?target+' was banned.':action==='remove'?target+' was removed.':action==='cohost'?target+' is now a co-host.':action==='transfer'?target+' is now the room host.':'Participant updated.','success')}catch(e){notice(e.message||'This moderation action could not be completed. Apply the latest SPIKE Rooms database migration if host transfer is unavailable.','error')}}
function renderInviteDirectory(){
 const host=$('inviteDirectory');if(!host)return;
 const q=($('inviteFriendsSearch')?.value||'').trim().toLowerCase();
 const visible=inviteFriends.filter(f=>!q||f.name.toLowerCase().includes(q)||f.username.includes(q));
 host.setAttribute('aria-busy','false');
 if(visible.length){host.innerHTML=visible.map(f=>{const disabled=inviteExisting.has(f.id),checked=inviteSelected.has(f.id);return `<label class="room-invite-person ${disabled?'is-invited':''} ${checked?'is-selected':''}"><input type="checkbox" data-invite-select="${esc(f.id)}" ${checked?'checked':''} ${disabled?'disabled':''} aria-label="Select ${esc(f.name)}">${avatar(f.profile)}<span class="room-invite-person-copy"><strong>${esc(f.name)}</strong><small>${disabled?'<i class="fa-solid fa-circle-check"></i> Already invited or in this room':`<i class="fa-solid fa-user-check"></i> @${esc(f.username||'SPIKE friend')}`}</small></span><span class="room-invite-friend-tag">${disabled?'Invited':'Friend'}</span></label>`}).join('')}
 else if(inviteFriends.length){host.innerHTML='<div class="room-invite-empty"><span><i class="fa-solid fa-magnifying-glass"></i></span><strong>No friends found</strong><small>Try another name or username.</small></div>'}
 else{host.innerHTML='<div class="room-invite-empty"><span><i class="fa-solid fa-user-group"></i></span><strong>Your SPIKE friends will appear here</strong><small>Add friends on SPIKE, then come back to invite them into this room.</small><a href="friends.html">Open Friends <i class="fa-solid fa-arrow-up-right-from-square"></i></a></div>'}
 const selectable=visible.filter(f=>!inviteExisting.has(f.id)),selectedVisible=selectable.filter(f=>inviteSelected.has(f.id)).length,all=$('inviteSelectAll');
 if(all){all.checked=selectable.length>0&&selectedVisible===selectable.length;all.indeterminate=selectedVisible>0&&selectedVisible<selectable.length;all.disabled=!selectable.length}
 const count=inviteSelected.size;$('inviteSelectedCount')?.replaceChildren(document.createTextNode(`${count} selected`));
 const send=$('sendRoomInvites');if(send)send.disabled=count===0||count>50;
 const countNode=$('inviteSendCount');if(countNode)countNode.textContent=String(count);
 const clear=$('clearInviteSearch');if(clear)clear.hidden=!q;
}
async function loadFriendsForInvites(){
 const host=$('inviteDirectory');if(!host||!room?.id)return;
 if(!isModerator()){host.setAttribute('aria-busy','false');host.innerHTML='<div class="room-invite-empty"><span><i class="fa-solid fa-shield-halved"></i></span><strong>Invitations are managed by the host</strong><small>Only the room host and co-hosts can invite friends.</small></div>';return}
 host.setAttribute('aria-busy','true');host.innerHTML='<div class="room-invite-loading"><span></span><span></span><span></span><small>Finding your SPIKE friends…</small></div>';
 try{
  const friendRows=[];let offset=0;
  while(offset<5000){const page=await db.rpc('get_friends_public',{p_limit:100,p_offset:offset});if(page.error)throw page.error;const batch=Array.isArray(page.data)?page.data:[];friendRows.push(...batch);offset+=batch.length;if(batch.length<100)break}
  const ids=[...new Set(friendRows.map(x=>String(x.user_id||x.id||x.friend_id||'')).filter(id=>uuidRE.test(id)&&id!==me.id))];
  const [profileChunks,existing]=await Promise.all([Promise.all(Array.from({length:Math.ceil(ids.length/250)},(_,i)=>getProfiles(ids.slice(i*250,(i+1)*250)))),db.from('spike_room_invites').select('invitee_id,status').eq('room_id',room.id).in('status',['pending','accepted'])]);
  if(existing.error)throw existing.error;
  const profiles=new Map(profileChunks.flatMap(m=>[...m]));inviteExisting=new Set((existing.data||[]).map(x=>String(x.invitee_id)));
  inviteFriends=ids.map(id=>{const p=profiles.get(id)||friendRows.find(x=>String(x.user_id||x.id||x.friend_id||'')===id)||{};const name=profileName(p);return{id,name,username:String(p.username||'').replace(/^@/,'').toLowerCase(),profile:p}}).sort((a,b)=>a.name.localeCompare(b.name));
  inviteSelected=new Set([...inviteSelected].filter(id=>inviteFriends.some(f=>f.id===id)&&!inviteExisting.has(id)).slice(0,50));
  const status=$('inviteSendStatus');if(status)status.textContent=inviteFriends.length?`${inviteFriends.length} friend${inviteFriends.length===1?'':'s'} available · Up to 50 per invite`:'No accepted friends yet.';
  renderInviteDirectory();
 }catch(e){console.error('[SPIKE Rooms] Could not load invitation friends:',e);host.setAttribute('aria-busy','false');host.innerHTML=`<div class="room-invite-empty is-error"><span><i class="fa-solid fa-triangle-exclamation"></i></span><strong>Your friends couldn't load</strong><small>${esc(e.message||'Check your connection and try again.')}</small><button type="button" id="retryRoomInviteFriends"><i class="fa-solid fa-rotate-right"></i> Try again</button></div>`}
}
